	pairVault: {
		parameters: {
			query?: never;
			header?: never;
			path?: never;
			cookie?: never;
		};
		requestBody: {
			content: {
				'application/json': {
					code: string;
					/** @description The server's host name, to name the token. */
					host?: string;
					/** @description The folder holds no notes yet. */
					empty?: boolean;
				};
			};
		};
		responses: {
			/** @description The token, shown once, and what to create in an empty vault. */
			200: {
				headers: {
					[name: string]: unknown;
				};
				content: {
					'application/json': {
						token: string;
						dir: string;
						folders: string[];
						/** @description Notes added to Axon for the first sync to write. */
						scaffold: string[];
						/** Format: date-time */
						expires_at: string;
					};
				};
			};
			400: components['responses']['Problem'];
			401: components['responses']['Problem'];
			429: components['responses']['Problem'];
		};
	};
